package lunr

import (
	"encoding/json"
	"os"
	"testing"
)

// TestStemmerParity: porterStem matches lunr.stemmer on corpus tokens and
// Porter edge cases (golden generated by testdata/gen/gen.js).
func TestStemmerParity(t *testing.T) {
	data, err := os.ReadFile("testdata/index_from_js.json")
	if err != nil {
		t.Fatal(err)
	}
	var f struct {
		Stems map[string]string `json:"stems"`
	}
	if err := json.Unmarshal(data, &f); err != nil {
		t.Fatal(err)
	}
	if len(f.Stems) < 100 {
		t.Fatalf("too few stem fixtures: %d", len(f.Stems))
	}
	for w, want := range f.Stems {
		if got := porterStem(w); got != want {
			t.Errorf("porterStem(%q) = %q, want %q", w, got, want)
		}
	}
}
